package com.lmspilot.assessment.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="assessment_assignments",uniqueConstraints=@UniqueConstraint(name="uq_assessment_assignment_target",columnNames={"assessment_id","assignee_type","assignee_id"})) public class AssessmentAssignmentEntity { @Id public UUID id=UUID.randomUUID(); @Column(name="assessment_id",nullable=false) public UUID assessmentId; @Enumerated(EnumType.STRING) @Column(name="assignee_type",nullable=false,length=30) public AssessmentAssigneeType assigneeType=AssessmentAssigneeType.USER; @Column(name="assignee_id",nullable=false) public UUID assigneeId; @Column(name="available_from") public Instant availableFrom; @Column(name="due_at") public Instant dueAt; @Column(nullable=false) public boolean required=true; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) public AssessmentAssignmentStatus status=AssessmentAssignmentStatus.ACTIVE; @Column(name="assigned_by",nullable=false) public UUID assignedBy; @Column(name="assigned_at",nullable=false) public Instant assignedAt=Instant.now(); @Column(name="updated_at",nullable=false) public Instant updatedAt=Instant.now(); public AssessmentAssignmentEntity(){} }
